import os, sys

def audit_ramdisk(path):
    files = 0
    dirs = 0
    symlinks = 0
    broken_symlinks = []
    valid_symlinks = []

    for root, dirnames, filenames in os.walk(path):
        dirs += len(dirnames)
        for d in dirnames:
            dp = os.path.join(root, d)
            if os.path.islink(dp):
                symlinks += 1
        for f in filenames:
            fp = os.path.join(root, f)
            if os.path.islink(fp):
                symlinks += 1
                target = os.readlink(fp)
                # check resolved target
                resolved = os.path.exists(fp)
                if resolved:
                    valid_symlinks.append((fp, target))
                else:
                    broken_symlinks.append((fp, target))
            else:
                files += 1
    return files, dirs, symlinks, valid_symlinks, broken_symlinks

for name, rpath in [('ramdisk_erase', 'extracted/ipsw/ramdisk_erase'), ('ramdisk_update', 'extracted/ipsw/ramdisk_update')]:
