    print(f'Files: {f}, Dirs: {d}, Symlinks: {s}')
    print(f'Valid Symlinks: {len(val)}, Broken Symlinks: {len(brk)}')
    if brk:
        print('Sample broken symlinks:')
        for b in brk[:10]:
            print(f'  {b[0]} -> {b[1]}')
